contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint testBefore = address(this).balance;
        uint contractBefore = address(c).balance;
        uint potBefore = c.pot();
        bool reverted;
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }
        if (amount == 10) {
            assert(!reverted);
            // Determine whether payout occurred: pot is reset to 0 from a positive amount, or stayed 0 if no payout from empty pot.
            // We can't reliably distinguish empty-pot no-payout from payout solely by pot, so use contract balance change:
            // If contract balance decreased, payout occurred; otherwise contract balance increased by amount.
            if (address(c).balance < contractBefore) {
                // Payout occurred: contract balance decreased by payout (potBefore + 10 - 1), test balance increased by payout.
                assert(address(this).balance == testBefore + (potBefore + amount - 1));
                assert(address(c).balance == contractBefore + amount - (potBefore + amount - 1));
            } else {
                // No payout: contract balance increased by amount, test balance decreased by amount.
                assert(address(this).balance == testBefore - amount);
                assert(address(c).balance == contractBefore + amount);
            }
        } else {
            assert(reverted);
            assert(address(this).balance == testBefore);
            assert(address(c).balance == contractBefore);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
