        uint contractBefore = address(c).balance;
        uint potBefore = c.pot();
        bool reverted;
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }
        bool success = !reverted;
        bool payoutOccurred = success && address(c).balance < contractBefore;
        bool exactAmount = (amount == 10);
        assert(
            (exactAmount && success && ((payoutOccurred && address(this).balance == testBefore + (potBefore + amount - 1) && address(c).balance == contractBefore + amount - (potBefore + amount - 1))
                                      || (!payoutOccurred && address(this).balance == testBefore - amount && address(c).balance == contractBefore + amount)))
            || (!exactAmount && reverted && address(this).balance == testBefore && address(c).balance == contractBefore)
        );
    }
    receive() external payable {}
}

