contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforePot = c.pot();
        uint beforeC = address(c).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPot = c.pot();
        uint afterC = address(c).balance;

        if (!reverted) {
            require(amount == 10, "unexpected success with wrong amount");
            // after a successful play, pot is either 0 (payout) or 10 (no payout)
            // and the contract's balance is either the previous balance + 10 - 10 = beforeC (payout)
            // or beforeC + 10 (no payout).
            // The general rule: afterPot == afterC - amount + 10 ?
            // If payout occurred: afterPot = 0, afterC = beforeC + 10 - 10 = beforeC, so afterC - amount + 10 = beforeC - 10 + 10 = beforeC = afterC. Not 0 generally.
            // better: when payout occurred, afterPot == 0 and afterC == beforeC;
            // when no payout, afterPot == 10 and afterC == beforeC + 10.
            // This is not expressible directly because beforeC known?
            // But we can express: afterPot is either 0 or TICKET_AMOUNT, and if afterPot == 0 then afterC == beforeC - 10? No, beforeC is not preserved after call? Yes it is, beforeC is a local variable.
            // The rule: afterPot == 0 ? afterC == beforeC - 10 : afterPot == 10 && afterC == beforeC + 10.
            // However, we need a general assert. Let's craft:
            assert(
                (afterPot == 0 && afterC == beforeC - 10) ||
                (afterPot == 10 && afterC == beforeC + 10 && amount == 10)
            );
        } else {
            assert(afterPot == beforePot && afterC == beforeC);
        }
    }

    receive() external payable {}
}

