        assert(
            (reverted && potAfter == potBefore && balanceAfter == balanceBefore) ||
            (!reverted && amount == 10 && ((potAfter != 0) == (balanceAfter == balanceBefore + 10)))
        );
    }

    receive() external payable {}
}

